/* Auth gate — only meaningful for the manual webhook input
   (schedule-triggered items carry no headers). */
const input = $input.first().json;
if (input.headers) {
  const provided = String(input.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (provided !== $env.CHAT_API_KEY) {
    return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
  }
}
return [{ json: { ok: true } }];

/* Collect sources: SearXNG searches per topic + platform status snapshot, then build the LLM request. */
const first = $input.first().json || {};
const body = first.body || {};
const topics = Array.isArray(body.topics) && body.topics.length > 0
  ? body.topics.slice(0, 5).map((t) => String(t).slice(0, 80))
  : ['AI 大模型 最新进展', '工作流自动化与 Agent 平台', '科技互联网要闻'];

const searches = [];
for (const topic of topics) {
  try {
    const res = await Promise.race([
      this.helpers.httpRequest({
        method: 'GET',
        url: 'http://searxng:8080/search',
        qs: { q: topic, format: 'json', time_range: 'week' },
        headers: { Accept: 'application/json' },
        timeout: 12000,
      }),
      new Promise((_, rej) => setTimeout(() => rej(new Error('search budget timeout')), 15000)),
    ]);
    searches.push({
      topic,
      results: (res.results || []).slice(0, 4).map((r) => ({
        title: r.title,
        url: r.url,
        snippet: String(r.content || '').slice(0, 220),
      })),
    });
  } catch (e) {
    searches.push({ topic, error: String(e && e.message ? e.message : e).slice(0, 150) });
  }
}

let platform = null;
try {
  platform = await Promise.race([
    this.helpers.httpRequest({
      method: 'GET',
      url: 'http://localhost:5678/webhook/admin/overview',
      headers: { Authorization: 'Bearer ' + $env.CHAT_API_KEY },
      timeout: 10000,
    }),
    new Promise((_, rej) => setTimeout(() => rej(new Error('overview budget timeout')), 10000)),
  ]);
} catch (e) {
  platform = null;
}

const briefDate = new Date().toISOString().slice(0, 10);
const sourcesText = JSON.stringify({
  topics: searches,
  platform: platform ? { chat_24h: platform.chat_24h, alerts_recent: (platform.alerts && platform.alerts.recent_count) || 0, kb: platform.kb } : null,
}, null, 1);

const system = '你是一份个人 AI 平台的晨报编辑。只使用给定的检索结果撰写中文晨报，禁止编造事实或链接。';
const user = [
  '请输出一份中文晨报（Markdown，不要用代码块包裹），结构：',
  '1) 第一行：晨报 · ' + briefDate + '；',
  '2) 按主题分节：每节 2–3 条要点，每条一句话概括 + 来源链接（[标题](链接) 格式，仅限给定结果）；',
  '3) 末尾「平台状态」一节：用给定 platform 数据写 1–2 句（无数据则写“数据暂缺”）；',
  '4) 全文不超过 500 字，语气克制专业。',
  '',
  '检索结果（JSON）：',
  sourcesText,
].join('\n');

const llm_body = {
  model: 'deepseek-chat',
  temperature: 0.4,
  max_tokens: 1200,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ],
};

return [{ json: { brief_date: briefDate, llm_body } }];

/* Parse the summary into a row ready for the daily_briefs table (autoMapInputData). */
const resp = $input.first().json;
const content = String((resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '').trim();
if (!content) throw new Error('empty summary from upstream');
const briefDate = new Date().toISOString().slice(0, 10);
const title = '晨报 · ' + briefDate;
// admin line: append the open-todos section (deterministic, best-effort)
let todoSec = '';
try {
  const api = (method, path, qs) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, qs });
  const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
  const tid = (tables.find((t) => t.name === 'todos') || {}).id;
  if (tid) {
    const rows = (await api('GET', '/data-tables/' + tid + '/rows', { limit: 200 })).data || [];
    const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
    const open = rows.filter((r) => r.status === 'open');
    const overdue = open.filter((r) => r.due_date && r.due_date < today);
    const dueToday = open.filter((r) => r.due_date && r.due_date === today);
    const rest = open.filter((r) => !r.due_date || r.due_date > today);
    if (open.length) {
      const fmt = (r) => r.text + (r.due_date ? '（' + r.due_date.slice(5) + '）' : '');
      const lines = ['', '## 待办速览'];
      if (overdue.length) lines.push('- 逾期 ' + overdue.length + ' 条：' + overdue.map(fmt).join('、'));
      if (dueToday.length) lines.push('- 今日到期 ' + dueToday.length + ' 条：' + dueToday.map(fmt).join('、'));
      if (rest.length) lines.push('- 其他未完成 ' + rest.length + ' 条' + (rest.length <= 5 ? '：' + rest.map(fmt).join('、') : ''));
      lines.push('（完成任意一条：直接说「XXX 办完了」）');
      todoSec = lines.join(String.fromCharCode(10));
    }
  }
} catch (e) { todoSec = ''; }
const contentFinal = content + todoSec;
const meta = JSON.stringify({ model: resp.model, usage: resp.usage, todos: todoSec ? 1 : 0 });
return [{ json: { title, content_md: contentFinal, brief_date: briefDate, meta } }];

