/* The 08:30 slot is useless on a host that is asleep at 08:30 — today the
   stack only came up around 10:28 and the brief never ran. Extra slots at
   11:30 / 15:30 are pure catch-up: daily_briefs has no dedup of its own, so
   without this guard an always-on host would produce three briefs a day. */
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
const list = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1/data-tables', qs: { limit: 100 }, headers: H });
const t = (list.data || []).find((x) => x.name === 'daily_briefs');
if (!t) return $input.all();
const rows = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1/data-tables/' + t.id + '/rows?limit=250&sortBy=createdAt%3Adesc', headers: H });
/* brief_date is written as a UTC date; the slots all map to the same UTC day */
const d = new Date();
const today = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
const done = ((rows.data || {}).data || []).some((r) => String(r.brief_date || '').slice(0, 10) === today);
if (done) return [];
return $input.all();
